namespace {
struct CommandAvailability : CCmdUI { bool enabled = true; void Enable(BOOL value) override { enabled = value != FALSE; m_bEnableChanged = TRUE; } void SetCheck(int) override {} void SetRadio(BOOL) override {} void SetText(LPCTSTR) override {} };
std::wstring Address(std::uint64_t offset) { wchar_t text[32]{}; swprintf_s(text,L"0x%llX",offset); return text; }
bool ParseOperation(const std::wstring& text,IntegerTransform* output,std::wstring* error) { std::wistringstream input(text); std::wstring op,endian,operand,extra; IntegerTransform result; if (!(input >> op >> result.width >> endian >> operand) || (input >> extra)) return false; const std::wstring names[] = {L"xor",L"and",L"or",L"add",L"subtract",L"left",L"right"}; const auto found = std::find(std::begin(names),std::end(names),op); if (found == std::end(names) || (endian != L"le" && endian != L"be") || (result.width != 8 && result.width != 16 && result.width != 32 && result.width != 64) || !ParseAddress(operand,&result.operand)) { if (error) *error = L"Example: xor 16 le FF. Use xor/and/or/add/subtract/left/right; widths 8/16/32/64; le/be; hex operand or d:decimal."; return false; } result.operation = static_cast<IntegerOperation>(found - std::begin(names)); result.little = endian == L"le"; const auto limit = result.width == 64 ? UINT64_MAX : (1ULL << result.width) - 1; if (result.operand > (result.operation >= IntegerOperation::ShiftLeft ? result.width - 1 : limit)) return false; *output = result; return true; }
}
void CMainFrame::OnWorkflow(UINT command) {
    if (command == ID_WORKFLOW_BACK || command == ID_WORKFLOW_FORWARD) { if (workspace_) workspace_->NavigateHistory(command == ID_WORKFLOW_BACK); return; }
    if (command == ID_WORKFLOW_PALETTE) { auto* menu = workspace_ ? workspace_->GetMenu() : GetMenu(); auto commands = CollectPaletteCommands(menu); const bool busy = IsBusy(); for (auto& item : commands) { CommandAvailability available; available.m_nID = item.id; if (workspace_) workspace_->OnCmdMsg(item.id,CN_UPDATE_COMMAND_UI,&available,nullptr); else OnCmdMsg(item.id,CN_UPDATE_COMMAND_UI,&available,nullptr); if (available.m_bEnableChanged) item.enabled = available.enabled; if ((item.id == ID_WORKFLOW_CHANGES || item.id == ID_WORKFLOW_STRINGS || item.id == ID_WORKFLOW_STRING_EXPORT) && (comparison_session_ || !document_.IsOpen())) item.enabled = false; if (item.id == ID_WORKFLOW_DECODING && !ActiveHex()) item.enabled = false; if (item.id == ID_WORKFLOW_STRING_EXPORT && (!strings_ || strings_revision_ != revision_)) item.enabled = false; if (item.id == ID_WORKFLOW_PALETTE || (busy && item.id != ID_FILE_COMPARE_CANCEL)) item.enabled = false; if (item.id == ID_WORKFLOW_INTEGERS && (comparison_session_ || !ActiveHex() || !hex_.SelectionLength() || MutationBlocked())) item.enabled = false; if (item.id == ID_WORKFLOW_FOLDER_RULES || (item.id >= ID_WORKFLOW_TREE && item.id <= ID_WORKFLOW_TREE_COLLAPSE)) item.enabled = item.enabled && AdvancedActive() && displayed_mode_ == 4; if (item.id == ID_WORKFLOW_CONTEXT) item.enabled = item.enabled && AdvancedActive() && (displayed_mode_ == 2 || displayed_mode_ == 3); } CCommandPalette dialog(this,std::move(commands)); path_dialog_ = true; const auto answer = dialog.DoModal(); path_dialog_ = false; if (answer == IDOK) { if (workspace_ && !IsWindowVisible()) { status_.SetPaneText(0,L"The active tab changed. Reopen command search for the intended document."); return; } if (workspace_) workspace_->SendMessage(WM_COMMAND,dialog.selected); else SendMessage(WM_COMMAND,dialog.selected); } return; }
    if (IsBusy()) return;
    if (command == ID_WORKFLOW_FOLDER_RULES || command == ID_WORKFLOW_CONTEXT || (command >= ID_WORKFLOW_TREE && command <= ID_WORKFLOW_TREE_COLLAPSE)) { if (AdvancedActive() && EnsureAdvanced()) advanced_.WorkflowSettings(command); else status_.SetPaneText(0,L"Open the relevant text/folder comparison first."); return; }
    if (command == ID_WORKFLOW_DECODING) { auto* view = ActiveHex(); if (!view) return; CValueDialog dialog(this,L"Read-only Hex decoding",L"0=off, 1=UTF-8, 2=UTF-16 LE, 3=UTF-16 BE, 4=Big5. The added column selects original bytes; click Hex/ASCII to edit. Ambiguous Big5 boundaries show dots.",std::to_wstring(static_cast<unsigned>(view->Decoding()))); std::uint64_t value = 0; dialog.validate = [&](const std::wstring& text,std::wstring*) { return ParseAddress(L"d:" + text,&value) && value <= 4; }; path_dialog_ = true; const auto answer = dialog.DoModal(); path_dialog_ = false; if (answer == IDOK) view->SetDecoding(static_cast<HexDecoding>(value)); return; }
    if (command == ID_WORKFLOW_CHANGE_PREVIOUS || command == ID_WORKFLOW_CHANGE_NEXT) { NavigateModification(command == ID_WORKFLOW_CHANGE_PREVIOUS); return; }
    if (command == ID_WORKFLOW_STRING_EXPORT) { ExportExtractedStrings(); return; }
    if (command == ID_WORKFLOW_INTEGERS) { if (comparison_session_ || ActiveHex() != &hex_ || MutationBlocked() || !hex_.SelectionLength()) { status_.SetPaneText(0,L"Select bytes in a writable file Hex page first."); return; } IntegerTransform operation; CFeatureInput dialog(this,L"Selected unsigned integer operation",L"operation width endian operand. Example: xor 16 le FF. Operations: xor/and/or/add/subtract/left/right. Width: 8/16/32/64, endian: le/be. Operand hex or d:decimal. Add/subtract wrap modulo 2^width. Shifts must be less than width. Selection <=64 MiB; one Undo; Save is separate.",L"xor 8 le FF"); dialog.validate = [&](const std::wstring& value,std::wstring* error) { return ParseOperation(value,&operation,error); }; path_dialog_ = true; const auto answer = dialog.DoModal(); path_dialog_ = false; if (answer == IDOK) StartWorkflowJob(command,operation); return; }
    if (command == ID_WORKFLOW_STRINGS) { CValueDialog dialog(this,L"Extract binary string previews",L"minimum,type-mask. Minimum 2-4096 characters. Type mask: ASCII=1, UTF-16 LE=2, UTF-16 BE=4; add flags, e.g. 4,7. First 100,000 results retained; text previews are bounded. Selection or whole file.",L"4,7"); unsigned minimum = 4,kinds = 7; dialog.validate = [&](const std::wstring& text,std::wstring*) { auto value = text; std::replace(value.begin(),value.end(),L',',L' '); std::wistringstream input(value); std::wstring extra; return (input >> minimum >> kinds) && !(input >> extra) && minimum >= 2 && minimum <= 4096 && kinds >= 1 && kinds <= 7; }; path_dialog_ = true; const auto answer = dialog.DoModal(); path_dialog_ = false; if (answer == IDOK) StartWorkflowJob(command,{},minimum,kinds); return; }
    if (command == ID_WORKFLOW_CHANGES) StartWorkflowJob(command);
}
bool CMainFrame::StartWorkflowJob(UINT command,const IntegerTransform& operation,unsigned minimum,unsigned kinds) {
    if (IsBusy() || comparison_session_ || !document_.IsOpen() || !ApplyTextEdits()) return false; const bool transform = command == ID_WORKFLOW_INTEGERS; if (transform && (MutationBlocked() || hex_.ReadOnly() || !hex_.SelectionLength())) return false; std::wstring error; auto snapshot = document_.Snapshot(&error,transform); if (!snapshot) { status_.SetPaneText(0,error.c_str()); return false; } const auto path = document_.Path(); const auto at = command == ID_WORKFLOW_CHANGES ? 0 : hex_.SelectionLength() ? hex_.SelectionStart() : 0, length = command == ID_WORKFLOW_CHANGES ? snapshot->Size() : hex_.SelectionLength() ? hex_.SelectionLength() : snapshot->Size();
    cancelled_ = false; progress_ = 0; job_revision_ = revision_; job_kind_ = transform ? EditorJobKind::Transform : command == ID_WORKFLOW_CHANGES ? EditorJobKind::WorkflowChanges : EditorJobKind::WorkflowStrings;
    try { job_ = std::async(std::launch::async,[this,snapshot = std::move(snapshot),operation,minimum,kinds,path,at,length,kind = job_kind_]() mutable { EditorJobResult result; result.kind = kind; SaveControl control; control.cancelled = &cancelled_; control.progress = [this](unsigned p) { progress_ = p; }; if (kind == EditorJobKind::Transform) { if (TransformIntegers(*snapshot,at,length,operation,control,&result.error)) { result.document = std::move(snapshot); result.count = 1; result.message = L"Unsigned integer operation applied. One Undo restores it; Save remains separate."; } }
        else if (kind == EditorJobKind::WorkflowStrings) { result.strings = std::make_shared<StringExtraction>(); if (!ExtractStrings(*snapshot,at,length,minimum,kinds,control,result.strings.get(),&result.error) && !cancelled_ && result.error.empty()) result.error = L"Could not read the captured string-extraction range."; }
        else { BinaryDocument baseline; result.modified = std::make_shared<std::vector<ModifiedRange>>(); if (baseline.Open(path,&result.error)) if (!FindModifiedRanges(baseline,*snapshot,control,result.modified.get(),&result.error) && !cancelled_ && result.error.empty()) result.error = L"Could not analyze the saved-baseline changes."; } return result; }); } catch (...) { status_.SetPaneText(0,L"Could not start the bounded background operation."); return false; } status_.SetPaneText(0,L"Processing the captured file draft in the background..."); return true;
}
void CMainFrame::FinishWorkflowJob(EditorJobResult result) {
    if (revision_ != job_revision_ || cancelled_ || !result.error.empty() || !document_.ValidateSource(true,&result.error)) { status_.SetPaneText(0,result.error.empty() ? L"Operation cancelled/stale; editor retained." : result.error.c_str()); return; }
    std::vector<std::vector<std::wstring>> rows;
    if (result.modified) { modified_ranges_ = std::move(*result.modified); modified_revision_ = revision_; hex_.modified_ranges = &modified_ranges_; hex_.Invalidate(); for (const auto& range : modified_ranges_) rows.push_back({Address(range.offset),std::to_wstring(range.length),Address(range.before),std::to_wstring(range.removed),range.state}); CReviewList dialog(this,L"Unsaved byte modifications versus saved disk",{L"Draft offset",L"Draft bytes",L"Saved offset",L"Saved bytes",L"State"},std::move(rows)); path_dialog_ = true; const auto answer = dialog.DoModal(); path_dialog_ = false; if (answer == IDOK && !dialog.selected.empty() && modified_revision_ == revision_) { const auto range = modified_ranges_[dialog.selected[0]]; ShowPage(0); hex_.SelectRange(range.offset,range.length); } status_.SetPaneText(0,(std::to_wstring(modified_ranges_.size()) + L" modified ranges. Highlights expire after another edit; review again to refresh.").c_str()); }
    else if (result.strings) { strings_ = std::move(result.strings); strings_revision_ = revision_; strings_source_ = {document_.Path(),document_.SourceIdentity()}; for (const auto& item : strings_->rows) rows.push_back({Address(item.offset),std::to_wstring(item.length),item.encoding,item.text}); CReviewList dialog(this,L"Extracted binary strings (bounded previews)",{L"Physical offset",L"Bytes",L"Encoding",L"Preview"},std::move(rows)); path_dialog_ = true; const auto answer = dialog.DoModal(); path_dialog_ = false; if (answer == IDOK && !dialog.selected.empty() && strings_revision_ == revision_) { const auto& item = strings_->rows[dialog.selected[0]]; ShowPage(0); hex_.SelectRange(item.offset,item.length); } status_.SetPaneText(0,(std::to_wstring(strings_->total) + L" strings found; " + std::to_wstring(strings_->rows.size()) + L" previews retained. Tools > Export extracted string previews writes CSV.").c_str()); }
}
void CMainFrame::NavigateModification(bool previous) {
    if (auto* editor = ActiveEditor()) { const auto line = editor->Call(SCI_LINEFROMPOSITION,editor->Call(SCI_GETCURRENTPOS)); const auto mask = (1 << SC_MARKNUM_HISTORY_MODIFIED) | (1 << SC_MARKNUM_HISTORY_REVERTED_TO_MODIFIED) | (1 << SC_MARKNUM_HISTORY_REVERTED_TO_ORIGIN); auto found = editor->Call(previous ? SCI_MARKERPREVIOUS : SCI_MARKERNEXT,previous ? line - 1 : line + 1,mask); if (found < 0) found = editor->Call(previous ? SCI_MARKERPREVIOUS : SCI_MARKERNEXT,previous ? editor->Call(SCI_GETLINECOUNT) - 1 : 0,mask); if (found >= 0) editor->GoToLine(found + 1); else status_.SetPaneText(0,L"No unsaved text change markers."); return; }
    if (modified_revision_ != revision_ || modified_ranges_.empty() || !document_.ValidateSource(true)) { status_.SetPaneText(0,L"Tools > Review unsaved byte modifications refreshes the saved-baseline ranges first."); return; } const auto at = hex_.CursorOffset(); auto found = std::upper_bound(modified_ranges_.begin(),modified_ranges_.end(),at,[](auto value,const auto& row) { return value < row.offset; }); if (previous) { found = std::lower_bound(modified_ranges_.begin(),modified_ranges_.end(),at,[](const auto& row,auto value) { return row.offset < value; }); if (found == modified_ranges_.begin()) found = modified_ranges_.end(); --found; } else if (found == modified_ranges_.end()) found = modified_ranges_.begin(); hex_.SelectRange(found->offset,found->length);
}
void CMainFrame::ExportExtractedStrings() {
    if (IsBusy() || !strings_ || strings_revision_ != revision_ || !document_.ValidateSource(true)) { status_.SetPaneText(0,L"Extract current binary strings before exporting their previews."); return; } CFileDialog dialog(FALSE,L"csv",L"strings.csv",OFN_OVERWRITEPROMPT,L"CSV (*.csv)|*.csv||",this); path_dialog_ = true; const auto answer = dialog.DoModal(); path_dialog_ = false; if (answer != IDOK) return; StartStringExport(dialog.GetPathName().GetString());
}
bool CMainFrame::StartStringExport(const std::wstring& path) {
    if (IsBusy() || !strings_ || strings_revision_ != revision_ || !document_.ValidateSource(true)) return false; job_locked_paths_ = {path}; if (workspace_ && !workspace_->LockPaths(job_locked_paths_,true,&job_)) { job_locked_paths_.clear(); return false; } const auto strings = strings_; const auto input = strings_source_; cancelled_ = false; progress_ = 0; job_revision_ = revision_; job_kind_ = EditorJobKind::Export;
    try { job_ = std::async(std::launch::async,[this,strings,input,path] { EditorJobResult result; result.kind = EditorJobKind::Export; std::wstring text = L"Offset,Bytes,Encoding,Preview\r\n"; for (const auto& item : strings->rows) { if (cancelled_) return result; text += Address(item.offset) + L"," + std::to_wstring(item.length) + L"," + item.encoding + L",\""; for (auto ch : item.text) { text += ch; if (ch == L'"') text += L'"'; } text += L"\"\r\n"; if (text.size() > 32 * 1024 * 1024) { result.error = L"CSV exceeds the 64 MiB text-buffer limit; narrow the extraction range."; return result; } } SaveControl control; control.cancelled = &cancelled_; TextOutputOptions options; if (ExportTextOutput(text,options,{input},path,control,&result.error)) result.message = L"Extracted string previews exported to " + path; return result; }); } catch (...) { ReleaseJobLocks(); status_.SetPaneText(0,L"Could not start CSV export."); return false; } return true;
}
